    # SubRefreshRequest is sent when a subscription is about to expire.
    #
    # @!attribute [r] client
    #   @return [String] The unique ID Centrifugo gave the connection.
    # @!attribute [r] transport
    #   @return [String] The connection's transport.
    # @!attribute [r] protocol
    #   @return [String] The client protocol: "json" or "protobuf".
    # @!attribute [r] encoding
    #   @return [String] "binary" when the proxy has binary_encoding enabled, so that
    #     payloads come in the b64 fields, and "json" otherwise.
    # @!attribute [r] user
    #   @return [String] The connection's user ID.
    # @!attribute [r] channel
    #   @return [String] The channel whose subscription is about to expire.
    # @!attribute [r] meta
    #   @return [Object, nil] The connection's meta, when the proxy has include_connection_meta.
    # @!attribute [r] labels
    #   @return [Hash{String => String}] PRO only — connection labels attached to the originating centrifuge.Client.
    #     Centrifugo PRO always populates this from Client.Labels() (no opt-in toggle).
    class SubRefreshRequest < Data.define(:client, :transport, :protocol, :encoding, :user, :channel, :meta, :labels)
      include Message

      def initialize(
        client: "",
        transport: "",
        protocol: "",
        encoding: "",
        user: "",
        channel: "",
        meta: nil,
        labels: {}
      )
        super
      end

      # The message as Centrifugo reads it, fields at their zero value left out.
      #
      # @api private
      def to_wire(where = "")
        w = {}
        Wire.put(w, "client", client, where, :str)
        Wire.put(w, "transport", transport, where, :str)
        Wire.put(w, "protocol", protocol, where, :str)
        Wire.put(w, "encoding", encoding, where, :str)
        Wire.put(w, "user", user, where, :str)
        Wire.put(w, "channel", channel, where, :str)
        Wire.put(w, "meta", meta, where, :json)
        Wire.put(w, "labels", labels, where, :str, :map)
        w
      end

      # The message from the Hash JSON.parse gives for it.
      #
      # @api private
      def self.from_wire(v, where = "SubRefreshRequest")
        d = Wire.obj(v, where)
        new(
          client: Wire.get(d, "client", where, :str),
          transport: Wire.get(d, "transport", where, :str),
          protocol: Wire.get(d, "protocol", where, :str),
          encoding: Wire.get(d, "encoding", where, :str),
          user: Wire.get(d, "user", where, :str),
          channel: Wire.get(d, "channel", where, :str),
          meta: Wire.get(d, "meta", where, :json),
          labels: Wire.get(d, "labels", where, :str, :map)
        )
      end
    end

    # SubRefreshResult extends the subscription, or ends it.
    #
    # @!attribute [r] expired
    #   @return [Boolean] Ends the subscription: it has expired.
    # @!attribute [r] expire_at
    #   @return [Integer] When the subscription expires next, in Unix seconds.
    # @!attribute [r] info
    #   @return [Object, nil] Replaces the channel-specific information about the connection, as
    #     JSON.
    # @!attribute [r] b64info
    #   @return [String] Info in base64, for binary info.
    # @!attribute [r] server_tags_filter
    #   @return [FilterNode, nil] When set, replaces the server-side tags filter of the
    #     subscription (Centrifugo PRO). When not set the filter is kept as it is.
    class SubRefreshResult < Data.define(:expired, :expire_at, :info, :b64info, :server_tags_filter)
      include Message

      def initialize(
        expired: false,
        expire_at: 0,
        info: nil,
        b64info: "",
        server_tags_filter: nil
      )
        super
      end

      # The message as Centrifugo reads it, fields at their zero value left out.
      #
      # @api private
      def to_wire(where = "")
        w = {}
        Wire.put(w, "expired", expired, where, :bool)
        Wire.put(w, "expire_at", expire_at, where, :int)
        Wire.put(w, "info", info, where, :json)
        Wire.put(w, "b64info", b64info, where, :str)
        Wire.put(w, "server_tags_filter", server_tags_filter, where, FilterNode)
        w
      end

      # The message from the Hash JSON.parse gives for it.
      #
      # @api private
      def self.from_wire(v, where = "SubRefreshResult")
        d = Wire.obj(v, where)
        new(
