          expire_at: Wire.get(d, "expire_at", where, :int),
          info: Wire.get(d, "info", where, :json),
          b64info: Wire.get(d, "b64info", where, :str),
          server_tags_filter: Wire.get(d, "server_tags_filter", where, FilterNode)
        )
      end
    end

