          epoch: Wire.get(d, "epoch", where, :str)
        )
      end
    end

    # SharedPollRefreshResultItem is an item's current data.
    #
    # @!attribute [r] key
    #   @return [String] The item's key.
    # @!attribute [r] data
    #   @return [Object, nil] The item's data. In versioned mode it may be left out for an
    #     item which has not changed.
    # @!attribute [r] version
    #   @return [Integer] The item's version: required in versioned mode, optional in
    #     versionless mode. It must grow when the item changes.
